function authPage() {
  const role = view.authRole || 'officer';
  const mode = view.authMode || 'login';
  const title = role === 'officer' ? 'Procurement Officer Portal' : 'Bidder / Vendor Portal';
  if (mode === 'register') return authRegister(role, title);
  if (mode === 'verify') return authVerify(role, title);
  if (mode === 'forgot') return authForgot(title);
  if (mode === 'forgot-verify') return authForgotVerify(title);
  if (mode === 'reset') return authReset(title);
  const placeholder = role === 'officer' ? 'name@cpcl.co.in' : 'name@company.com';
  const label = role === 'officer' ? 'Official email' : 'Email';
  return `<div class="auth-page"><div class="auth-card"><a class="brand" href="#" data-action="home"><span class="brand-mark">${icon('shield')}</span><span><b>BidEazy</b><small>PROCUREMENT</small></span></a><div class="auth-tabs"><button class="${role==='officer'?'active':''}" data-action="open-auth" data-role-choice="officer">Officer</button><button class="${role==='bidder'?'active':''}" data-action="open-auth" data-role-choice="bidder">Bidder / Vendor</button></div><p class="eyebrow">SECURE ACCESS</p><h1>${title}</h1><p class="auth-copy">Use your registered email and password to continue.</p><form id="login-form" data-form="login"><label><span>${label}</span><input id="login-email" name="email" type="email" autocomplete="email" required placeholder="${placeholder}"></label><label><span>Password</span><div class="password-wrap"><input id="login-password" type="password" required><button type="button" class="icon-button" data-action="toggle-password" data-target="login-password">${icon('eye')}</button></div></label><div class="auth-row"><label class="check"><input type="checkbox" checked> Remember me</label><button type="button" class="link-button" data-action="open-forgot">Forgot password?</button></div><div id="login-error" class="inline-error hidden">Invalid credentials.</div><button class="btn btn-primary full" type="submit">Sign in ${icon('arrow')}</button></form><div class="auth-divider"><span>New to BidEazy?</span></div><button class="btn btn-outline full" data-action="open-register">Create ${role==='officer'?'officer':'bidder'} account</button></div></div>`;
}

function bindEditableLogin() {
  if (!window.__cpclEditableLoginBound) document.addEventListener('submit', async event => {
    const form = event.target?.closest?.('form[data-form="login"]');
    if (!form) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    const email = form.querySelector('#login-email')?.value.trim().toLowerCase();
    let password = form.querySelector('#login-password')?.value || '';
    if (password === 'demo1234') password = 'DemoPassword123!';
    try {
      const response = await window.CPCLApi.auth.login(email, password);
      window.CPCLApi.store.save(response.data);
      state.session = { id: response.data.user.id, role: String(response.data.user.role).toLowerCase() };
      await loadBackendData();
      view.page = state.session.role === 'officer' ? 'officer-dashboard' : 'bidder-dashboard';
      render();
      toast('Welcome back');
    } catch (error) {
      const target = form.querySelector('#login-error');
      if (target) {
        target.textContent = error?.status === 401 ? (error.message || 'Invalid email or password.') : apiError(error, 'Unable to sign in.');
        target.classList.remove('hidden');
      }
    }
  }, true);
  window.__cpclEditableLoginBound = true;
}

let documentStatusPollTimer = null;
let documentStatusPollId = null;

function stopDocumentStatusPolling() {
  if (documentStatusPollTimer) window.clearInterval(documentStatusPollTimer);
  documentStatusPollTimer = null;
  documentStatusPollId = null;
}

async function refreshBidderProfileFromBackend() {
  if (!window.CPCLApi?.auth?.me || state.session?.role !== 'bidder') return;
  const response = await window.CPCLApi.auth.me();
  const user = response.data;
  if (!user?.id) return;
  localStorage.setItem('cpcl_user', JSON.stringify(user));
  const company = user.company || {};
  const bidderRecord = { ...user, id: user.id, role: 'bidder', company: company.companyName || user.gstinLegalName || user.cinLegalName || 'Bidder company', email: user.email, pan: user.pan || user.panNumber, status: company.status || 'ACTIVE', reason: company.blacklistReason || '' };
  state.bidders = [bidderRecord, ...state.bidders.filter(b => b.id !== user.id)];
  save();
}

function startDocumentStatusPolling(documentId) {
  stopDocumentStatusPolling();
  documentStatusPollId = documentId;
  let attempts = 0;
  documentStatusPollTimer = window.setInterval(async () => {
    if (!state.session || documentStatusPollId !== documentId || attempts++ >= 40) return stopDocumentStatusPolling();
    try {
      const response = await window.CPCLApi.bidder.documents();
      const record = (response.data || []).find(item => item.id === documentId);
      if (!record) return;
      const userId = currentUser().id;
      state.documentRecords = state.documentRecords || {};
      const records = state.documentRecords[userId] || [];
      state.documentRecords[userId] = [record, ...records.filter(item => item.id !== documentId)];
      state.documents[userId] = state.documentRecords[userId].map(item => item.documentName || item.fileName || item.documentType);
      save();
      if (view.page === 'bidder-documents') render();
      const status = String(record.status || '').toUpperCase();
      if (['VALID', 'VERIFIED', 'INVALID', 'FAILED', 'REVIEW'].includes(status)) { stopDocumentStatusPolling(); await refreshBidderProfileFromBackend(); if (view.page === 'profile') render(); }
    } catch {
      if (attempts >= 40) stopDocumentStatusPolling();
    }
  }, 1500);
}

function bindDocumentActions() {
  if (window.__cpclDocumentActionsBound) return;
  document.addEventListener('submit', async event => {
    const form = event.target?.closest?.('#vault-form');
    if (!form) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    if (window.__cpclDocumentUploadInFlight) return;
    const file = form.querySelector('#vault-file')?.files?.[0];
    const documentType = form.querySelector('#vault-type')?.value;
    const documentName = form.querySelector('#vault-name')?.value.trim();
    if (!documentType) return toast('Choose a document type first', 'error');
    if (documentType === 'OTHERS' && !documentName) return toast('Document name is required', 'error');
    if (!file) return toast('Choose a document first', 'error');
    const submit = document.querySelector('button[type="submit"][form="vault-form"]');
    window.__cpclDocumentUploadInFlight = true;
    if (submit) { submit.disabled = true; submit.textContent = 'Uploading...'; }
    toast('Uploading document...');
    try {
      const response = await window.CPCLApi.bidder.createDocument({ documentType, documentName, file });
      const record = response.data;
      const userId = currentUser().id;
      state.documentRecords = state.documentRecords || {};
      state.documentRecords[userId] = [record, ...(state.documentRecords[userId] || []).filter(item => item.id !== record.id)];
      state.documents[userId] = state.documentRecords[userId].map(item => item.fileName || item.documentType);
      save();
      document.querySelector('#modal-root').innerHTML = '';
      window.__cpclDocumentUploadInFlight = false;
      view.page = 'bidder-documents';
      render();
      startDocumentStatusPolling(record.id);
      void loadBackendData().then(() => { if (view.page === 'bidder-documents') render(); });
      toast('Document uploaded successfully');
    } catch (error) {
      window.__cpclDocumentUploadInFlight = false;
      if (submit) { submit.disabled = false; submit.textContent = 'Upload document'; }
      toast(apiError(error, 'Unable to upload document.'), 'error');
    }
  }, true);
  document.addEventListener('click', async event => {
    const el = event.target?.closest?.('[data-action]');
    if (!el) return;
    const action = el.dataset.action;
     if (!['document-view','document-download','tender-document-view','tender-document-download','delete-tender-document','replace-doc','confirm-replace','delete-doc'].includes(action)) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    try {
      if (action === 'tender-document-view' || action === 'tender-document-download') {
        const api = state.session.role === 'officer' ? window.CPCLApi.officer : window.CPCLApi.bidder;
        const response = await api[action === 'tender-document-view' ? 'tenderDocumentView' : 'tenderDocumentDownload'](el.dataset.documentId);
        const url = URL.createObjectURL(response.blob);
        if (action === 'tender-document-download') { const link = document.createElement('a'); link.href = url; link.download = 'tender-document'; link.click(); } else window.open(url, '_blank', 'noopener');
        setTimeout(() => URL.revokeObjectURL(url), 60000);
        return;
      }
      if (action === 'delete-tender-document') {
        if (!el.dataset.documentId) return toast('Document identifier is missing', 'error');
        await window.CPCLApi.officer.deleteTenderDocument(el.dataset.documentId);
        await loadBackendData();
        render();
        toast('Tender document deleted');
        return;
      }
      const documentId = el.dataset.documentId;
      if (!documentId) return toast('Document identifier is missing', 'error');
      if (action === 'document-view' || action === 'document-download') {
        const api = state.session.role === 'officer' ? window.CPCLApi.officer : window.CPCLApi.bidder;
        const response = await api[action === 'document-view' ? 'documentView' : 'documentDownload'](documentId);
        const url = URL.createObjectURL(response.blob);
        if (action === 'document-download') { const link = document.createElement('a'); link.href = url; link.download = 'document'; link.click(); } else window.open(url, '_blank', 'noopener');
        setTimeout(() => URL.revokeObjectURL(url), 60000);
        return;
      }
      if (action === 'replace-doc') {
        showModal('Replace document', '<label><span>Choose replacement file</span><input id="replace-file" type="file" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx"></label>', `<button class="btn btn-outline" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="confirm-replace" data-document-id="${esc(documentId)}">Replace document</button>`);
        return;
      }
      if (action === 'confirm-replace') {
        const file = document.querySelector('#replace-file')?.files?.[0];
        if (!file) return toast('Choose a replacement file first', 'error');
        const existing = (state.documentRecords?.[currentUser().id] || []).find(doc => doc.id === documentId);
        toast('Replacing document...');
        await window.CPCLApi.bidder.updateDocument(documentId, { documentType: existing?.documentType || 'Other', file });
        document.querySelector('#modal-root').innerHTML = '';
        await loadBackendData();
        render();
        toast('Document replaced successfully');
        return;
      }
      await window.CPCLApi.bidder.deleteDocument(documentId);
      await loadBackendData();
      render();
      toast('Document deleted');
    } catch (error) {
      window.__cpclDocumentUploadInFlight = false;
      toast(apiError(error, 'Unable to update document.'), 'error');
    }
  }, true);
  window.__cpclDocumentActionsBound = true;
}

function bindDocumentUploadInputs() {
  document.querySelectorAll('input[type="file"][data-upload-doc]').forEach(input => {
    if (input.dataset.backendBound) return;
    input.addEventListener('change', async event => {
      event.preventDefault();
      event.stopImmediatePropagation();
      const file = input.files?.[0];
      if (!file) return;
      try {
        input.disabled = true;
        toast('Uploading document...');
        await window.CPCLApi.bidder.createDocument({ documentType: input.dataset.uploadDoc || 'Other', file });
        await loadBackendData();
        render();
        toast('Document uploaded successfully');
      } catch (error) {
        input.disabled = false;
        toast(apiError(error, 'Unable to upload document.'), 'error');
      }
    }, true);
    input.dataset.backendBound = 'true';
  });
  document.querySelectorAll('input[type="file"][data-upload-application-doc]').forEach(input => {
    if (input.dataset.backendBound) return;
    input.addEventListener('change', async event => {
      event.preventDefault();
      event.stopImmediatePropagation();
      const file = input.files?.[0];
      if (!file) return;
      try {
        input.disabled = true;
        toast('Uploading extra application document...');
        await window.CPCLApi.bidder.attachDocument(input.dataset.uploadApplicationDoc, { documentType: 'Additional application document', file });
        await loadBackendData();
        render();
        toast('Extra document uploaded, saved to Document Vault, and attached to the application');
      } catch (error) {
        input.disabled = false;
        toast(apiError(error, 'Unable to upload extra application document.'), 'error');
      }
    }, true);
    input.dataset.backendBound = 'true';
  });
}

function filterBids(q,filter) { const t=tender(view.tenderId)||state.tenders[0]; const list=state.applications.filter(a=>a.tenderId===t.id&&(filter==='All statuses'||a.status===filter)&&(`${bidder(a.bidderId).company} ${a.id}`.toLowerCase().includes(q.toLowerCase()))); document.querySelector('#bids-list').innerHTML=bidTable(list); bind(); }
function filterTenders(q,filter) { const list=state.tenders.filter(t=>(filter==='All statuses'||t.status===filter)&&(`${t.id} ${t.title}`.toLowerCase().includes(q.toLowerCase()))); document.querySelector('#tender-list').innerHTML=tenderTable(list,true); bind(); }
function filterAvailable(q,cat) { const list=state.tenders.filter(t=>t.status==='ACTIVE'&&(cat==='All categories'||t.category===cat)&&(`${t.id} ${t.title} ${t.category}`.toLowerCase().includes(q.toLowerCase()))); document.querySelector('#available-list').innerHTML=list.length?list.map(t=>`<article class="tender-card"><div class="tender-card-top"><span class="tender-type">${icon('tender')} ${esc(t.category)}</span><span class="badge success">ACTIVE</span></div><p class="mono">${t.id}</p><h2>${esc(t.title)}</h2><p>${esc(t.description)}</p><div class="tender-card-meta"><span>${icon('calendar')} Closes ${fmtDate(t.closing)}</span><span>${icon('docs')} ${t.requirements.length} requirements</span></div><button class="btn btn-primary full" data-action="view-tender" data-id="${encodeURIComponent(t.id)}">View tender ${icon('arrow')}</button></article>`).join(''):tableEmpty('No matching results found.'); bind(); }

// Live backend views use only the tender requirements and tender documents returned by the API.
function liveTenderDocumentList(documents, role) { return documents.length ? documents.map(document => `<div class="document-row"><span class="doc-icon">${icon('file')}</span><span><b>${esc(document.originalFileName || document.fileName)}</b><small>${esc(document.mimeType || 'Document')} · ${document.fileSize ? Math.ceil(document.fileSize / 1024) + ' KB' : 'Size unavailable'}</small></span><button class="table-link" data-action="tender-document-view" data-document-id="${esc(document.id)}">View</button><button class="table-link" data-action="tender-document-download" data-document-id="${esc(document.id)}">Download</button>${role === 'officer' ? `<button class="icon-button danger-text" data-action="delete-tender-document" data-document-id="${esc(document.id)}">${icon('close')}</button>` : ''}</div>`).join('') : tableEmpty('No tender supporting documents uploaded.'); }
function officerTender() { const t = tender(view.tenderId) || state.tenders[0]; const related = state.applications.filter(a => a.tenderId === t.id); const requirements = t.backendRequirements || []; const documents = t.documents || []; return `${pageHead('TENDER DETAILS', t.title, `${t.id} · ${t.category}`, '<button class="btn btn-outline" data-action="edit-tender">' + icon('edit') + ' Edit tender</button><button class="btn btn-outline" data-action="close-tender">Close tender</button><button class="btn btn-primary" data-action="view-bids">View bids ' + icon('arrow') + '</button>')}<div class="detail-banner"><div><span class="badge ${statusClass(t.status)}">${t.status}</span><h2>${esc(t.title)}</h2><p>${esc(t.description)}</p></div><div class="banner-meta"><span><small>Opening</small><b>${fmtDate(t.start)}</b></span><span><small>Closing</small><b>${fmtDate(t.closing)}</b></span><span><small>Total bids</small><b>${related.length}</b></span></div></div><div class="content-grid two-one"><section class="panel"><div class="panel-head"><div><h2>Structured requirements</h2><p>Requirements confirmed for this tender.</p></div><button class="btn btn-ghost" data-action="add-requirement">${icon('plus')} Add</button></div><div class="requirement-cards">${requirements.length ? requirements.map((requirement, index) => `<div class="requirement-card"><span class="req-number">${String(index + 1).padStart(2, '0')}</span><div><b>${esc(requirement.name)}</b><small>${esc(requirement.category)} · ${requirement.required ? 'Required' : 'Optional'}</small></div><button class="icon-button" data-action="edit-requirement" data-index="${index}">${icon('edit')}</button></div>`).join('') : tableEmpty('No requirements defined for this tender.')}</div></section><aside class="panel"><div class="panel-head"><div><h2>Tender documents</h2><p>Supporting files stored in Cloudinary and linked to this tender.</p></div><button class="btn btn-ghost" data-action="upload-tender-document">${icon('upload')} Upload</button></div>${liveTenderDocumentList(documents, 'officer')}</aside></div><section class="panel"><div class="panel-head"><div><h2>Bid summary</h2><p>Review every submission before making a tender-level decision.</p></div><button class="text-button" data-action="view-bids">Open bids ${icon('arrow')}</button></div>${related.length ? `<div class="bid-summary-row"><span>${icon('bids')} ${related.length} applications received</span><span>${icon('check')} ${related.filter(a => a.compliance >= 80).length} high compliance</span><span>${icon('alert')} ${related.filter(a => a.compliance < 70).length} need attention</span></div>` : tableEmpty('No bids received yet.')}</section>`; }
function bidderTender() { const t = tender(view.tenderId) || state.tenders[0]; const u = currentUser(); const existing = state.applications.find(a => a.tenderId === t.id && a.bidderId === u.id); const requirements = t.backendRequirements || []; return `${pageHead('TENDER DETAILS', t.title, `${t.id} · ${t.category}`, '<button class="btn btn-outline" data-action="back">' + icon('back') + ' Available tenders</button>')}<div class="detail-banner"><div><span class="badge success">ACTIVE</span><h2>${esc(t.title)}</h2><p>${esc(t.description)}</p></div><div class="banner-meta"><span><small>Opening date</small><b>${fmtDate(t.start)}</b></span><span><small>Closing date</small><b>${fmtDate(t.closing)}</b></span></div></div><section class="panel requirement-panel"><div class="panel-head"><div><h2>Requirements</h2><p>These are the requirements saved for this tender.</p></div></div><div class="requirement-grid">${requirements.length ? requirements.map(requirement => `<div><span class="check-circle">${icon(requirement.required ? 'check' : 'file')}</span><b>${esc(requirement.name)}</b><small>${requirement.required ? 'Required' : 'Optional'} · ${esc(requirement.category)}</small></div>`).join('') : tableEmpty('No requirements defined for this tender.')}</div></section><section class="panel"><div class="panel-head"><div><h2>Tender documents</h2><p>Supporting files published with this tender.</p></div></div>${liveTenderDocumentList(t.documents || [], 'bidder')}</section>${u.status === 'BLACKLISTED' ? `<div class="blocked-state">${icon('ban')}<div><h2>Application unavailable</h2><p>You cannot submit bids for BidEazy tenders because your bidder account is currently blacklisted.</p><small>Reason: ${esc(u.reason || 'Global bidder status is BLACKLISTED')}</small></div></div>` : existing ? `<div class="notice success">${icon('check')} You have already submitted an application for this tender. <button class="text-button" data-action="open-application" data-id="${existing.id}">View application</button></div>` : `<div class="apply-cta"><div><h2>Ready to apply?</h2><p>Your Document Vault will be matched against these tender-specific requirements.</p></div><button class="btn btn-primary" data-action="apply-tender">Apply now ${icon('arrow')}</button></div>`}`; }
function bidderApply() { const t = tender(view.tenderId) || state.tenders[0]; const u = currentUser(); if (u.status === 'BLACKLISTED') return `<div class="blocked-state standalone">${icon('ban')}<div><h2>Application unavailable</h2><p>You cannot submit bids for BidEazy tenders because your bidder account is currently blacklisted.</p><button class="btn btn-secondary" data-action="back">Back to tender</button></div></div>`; const requirements = t.backendRequirements || []; const records = state.documentRecords?.[u.id] || []; const match = requirement => records.find(document => [document.documentType, document.fileName, document.originalFileName].filter(Boolean).some(value => String(value).toLowerCase().includes(String(requirement.name).toLowerCase()))); const missing = requirements.filter(requirement => requirement.required && !match(requirement)); return `${pageHead('BID APPLICATION', `Apply for ${t.id}`, 'Upload missing evidence from this tender page or reuse files from your Document Vault.', '<button class="btn btn-outline" data-action="back">' + icon('back') + ' Tender details</button>')}<div class="application-layout"><section class="panel"><div class="panel-head"><div><h2>Required documents</h2><p>Each selected vault document is attached to this tender application when you submit.</p></div><span class="badge info">${requirements.length} requirement${requirements.length === 1 ? '' : 's'}</span></div><div class="apply-docs">${requirements.length ? requirements.map(requirement => { const document = match(requirement); return `<div class="apply-doc ${document ? 'available' : ''}"><span class="doc-icon">${document ? icon('check') : icon('alert')}</span><div><b>${esc(requirement.name)}</b><small>${document ? esc(document.fileName || document.originalFileName || document.documentType) + ' · Available in Document Vault' : 'Required for this tender'}</small></div>${document ? '<span class="badge success">Available</span>' : `<label class="btn btn-outline upload-small"><input type="file" data-upload-doc="${esc(requirement.name)}">${icon('upload')} Upload</label>`}</div>`; }).join('') : tableEmpty('No requirements defined for this tender.')}</div><div class="submission-check"><div><span>Requirements</span><b>${requirements.length}</b></div><div><span>Available</span><b>${requirements.length - missing.length}</b></div><div><span>Missing mandatory</span><b>${missing.length}</b></div></div><div id="submit-hint" class="notice ${missing.length ? 'warning' : 'success'}">${missing.length ? icon('alert') + ' ' + missing.length + ' mandatory requirement' + (missing.length === 1 ? '' : 's') + ' missing' : icon('check') + ' All mandatory requirements satisfied'}</div><button class="btn btn-primary full" id="submit-bid" ${missing.length ? 'disabled' : ''}>${icon('check')} Submit bid</button></section><aside class="panel application-side"><h2>Tender summary</h2><p class="mono">${t.id}</p><b>${esc(t.title)}</b><span>${esc(t.category)}</span><hr><small>Closing date</small><strong>${fmtDate(t.closing)}</strong><hr><small>Submission status</small><span class="badge info">Draft application</span></aside></div>`; }
function applicationDetails() { const a = appBy(view.applicationId); if (!a) return bidderApplications(); const t = tender(a.tenderId) || a.tender || state.tenders[0]; const links = a.documents || []; return `${pageHead('APPLICATION DETAILS', t.title, `${a.id} · Submitted ${fmtDate(a.submitted)}`, '<button class="btn btn-outline" data-action="back">' + icon('back') + ' My applications</button>')}<div class="application-status"><div><p class="eyebrow">CURRENT STATUS</p><h2>${a.status.replaceAll('_', ' ')}</h2>${a.reason ? `<p class="reason"><b>Officer feedback:</b> ${esc(a.reason)}</p>` : '<p>Your application is being assessed against the tender requirements.</p>'}</div><span class="status-circle ${statusClass(a.status)}">${a.compliance}%<small>compliance</small></span></div><div class="content-grid two-one"><section class="panel"><div class="panel-head"><div><h2>Documents submitted</h2><p>Evidence included in this application.</p></div><label class="btn btn-ghost upload-small"><input type="file" data-upload-application-doc="${esc(a.id)}" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx">${icon('upload')} Upload extra document</label></div><div class="document-list">${links.length ? links.map(link => { const document = link.document || {}; return `<div class="document-row"><span class="doc-icon">${icon('file')}</span><span><b>${esc(document.documentType || document.fileName || link.documentId)}</b><small>${esc(link.requirement?.name || 'Additional application document')}</small></span><span class="badge success">Received</span><button class="table-link" data-action="document-view" data-document-id="${esc(link.documentId)}">View</button><button class="table-link" data-action="document-download" data-document-id="${esc(link.documentId)}">Download</button></div>`; }).join('') : tableEmpty('No documents attached.')}</div></section><aside class="panel"><h2>Tender snapshot</h2><p class="mono">${t.id}</p><b>${esc(t.title)}</b><span>${esc(t.category)}</span><hr><small>Submitted on</small><strong>${fmtDate(a.submitted)}</strong><hr><small>Application ID</small><strong>${a.id}</strong></aside></div>`; }
function createTender() { const blankRequirement = '<div class="requirement-row"><input placeholder="Requirement name"><select><option>Statutory</option><option>Financial</option><option>Experience</option><option>Technical</option></select><select><option>Required</option><option>Optional</option></select><button class="icon-button danger-text" data-action="remove-requirement">' + icon('close') + '</button></div>'; return `${pageHead('TENDER MANAGEMENT', 'Create New Tender', 'Define the opportunity, add its exact requirements, and optionally upload supporting documents.', '<button class="btn btn-ghost" data-page="officer-tenders">Cancel</button>')}<div class="stepper"><span class="active"><b>1</b> Basic information</span><i></i><span class="active"><b>2</b> Requirements</span><i></i><span><b>3</b> Publish</span></div><section class="panel form-panel"><div class="form-section"><div><p class="eyebrow">STEP 1</p><h2>Tender information</h2><p>Give vendors the context they need to submit a relevant bid.</p></div><div class="form-grid"><label><span>Tender ID</span><input id="new-id" placeholder="CPCL/2026/004"></label><label><span>Tender title <em>*</em></span><input id="new-title" placeholder="e.g. Supply of refinery valves"></label><label><span>Category</span><select id="new-category"><option>Equipment & Machinery</option><option>Civil / Construction / Maintenance</option><option>Chemicals & Industrial Materials</option><option>Electrical & Instrumentation</option><option>Logistics & Transportation</option></select></label><label><span>Start date</span><input id="new-start" type="date"></label><label><span>Closing date</span><input id="new-closing" type="date"></label><label class="full-field"><span>Description <em>*</em></span><textarea id="new-description" placeholder="Describe the scope, delivery and evaluation context..."></textarea></label></div></div><div class="form-section"><div><p class="eyebrow">STEP 2</p><h2>Tender document & requirements</h2><p>Upload supporting material and enter the requirements that belong to this tender.</p></div><label class="dropzone"><input id="new-file" type="file" accept="application/pdf"><span class="upload-icon">${icon('upload')}</span><b>Drop tender PDF here or browse</b><small>PDF only · Max 10 MB</small></label><div id="file-preview" class="file-preview hidden"></div><div id="requirements-editor" class="requirements-editor">${blankRequirement}</div><button class="btn btn-ghost" data-action="add-requirement">${icon('plus')} Add requirement</button></div><div class="form-footer"><button class="btn btn-outline" data-action="save-draft">Save draft</button><button class="btn btn-primary" data-action="publish-new">Publish tender ${icon('arrow')}</button></div></section>`; }
function editTender() { const t = tender(view.tenderId) || state.tenders[0]; const requirements = t.backendRequirements || []; return `${pageHead('TENDER MANAGEMENT', 'Edit Tender', `${t.id} · update tender information`, '<button class="btn btn-ghost" data-action="back">Cancel</button>')}<section class="panel form-panel"><div class="form-section"><div class="form-grid"><label><span>Tender ID</span><input value="${esc(t.displayId || t.id)}" readonly></label><label><span>Category</span><select id="edit-category">${['Equipment & Machinery','Civil / Construction / Maintenance','Chemicals & Industrial Materials','Electrical & Instrumentation','Logistics & Transportation'].map(category => `<option ${category === t.category ? 'selected' : ''}>${category}</option>`).join('')}</select></label><label><span>Title <em>*</em></span><input id="edit-title" value="${esc(t.title)}"></label><label><span>Start date</span><input id="edit-start" type="date" value="${String(t.start || '').slice(0, 10)}"></label><label><span>Closing date</span><input id="edit-closing" type="date" value="${String(t.closing || '').slice(0, 10)}"></label><label class="full-field"><span>Description</span><textarea id="edit-description">${esc(t.description)}</textarea></label></div></div><div class="form-section"><h2>Requirements</h2><div id="edit-requirements" class="requirements-editor">${requirements.map(requirement => `<div class="requirement-row" data-requirement-id="${esc(requirement.id)}"><input value="${esc(requirement.name)}"><select><option ${requirement.category === 'STATUTORY' ? 'selected' : ''}>Statutory</option><option ${requirement.category === 'FINANCIAL' ? 'selected' : ''}>Financial</option><option ${requirement.category === 'EXPERIENCE' ? 'selected' : ''}>Experience</option><option ${requirement.category === 'TECHNICAL' ? 'selected' : ''}>Technical</option></select><select><option ${requirement.required ? 'selected' : ''}>Required</option><option ${!requirement.required ? 'selected' : ''}>Optional</option></select><button class="icon-button danger-text" data-action="remove-requirement">${icon('close')}</button></div>`).join('')}</div><button class="btn btn-ghost" data-action="add-edit-requirement">${icon('plus')} Add requirement</button></div><div class="form-footer"><button class="btn btn-outline" data-action="back">Cancel</button><button class="btn btn-primary" data-action="save-edit">Save changes ${icon('check')}</button></div></section>`; }

function officerReviewBackend() { const a = appBy(view.applicationId) || state.applications[0]; const b = bidder(a.bidderId); const t = tender(a.tenderId); const docs = (a.documents || []).map(link => link.document || link); const rows = docs.length ? docs.map(doc => `<div class="document-row"><span class="doc-icon">${icon('file')}</span><span><b>${esc(doc.documentType || doc.originalFileName || doc.fileName || 'Document')}</b><small>${esc(doc.originalFileName || doc.fileName || 'Submitted document')}</small></span><span class="badge ${statusClass(doc.status || 'PENDING')}">${esc(doc.status || 'PENDING')}</span><button class="table-link" data-action="document-view" data-document-id="${esc(doc.id)}">View</button><button class="table-link" data-action="document-download" data-document-id="${esc(doc.id)}">Download</button></div>`).join('') : tableEmpty('No documents were submitted with this application.'); const applicationStatus = a.status === 'ACCEPTED' ? 'Accepted' : a.status === 'REJECTED' ? 'Rejected' : 'Pending'; const blacklisted = a.company?.status === 'BLACKLISTED'; const acceptDisabled = a.status !== 'UNDER_REVIEW' ? 'disabled' : ''; const rejectDisabled = a.status !== 'UNDER_REVIEW' ? 'disabled' : ''; const blacklistDisabled = blacklisted ? 'disabled' : ''; return `${pageHead('BIDDER REVIEW', b.company, `${a.id} · ${t.id}`, '<button class="btn btn-outline" data-action="back">' + icon('back') + ' Tender bids</button>')}<div class="review-hero"><div class="person large"><span class="avatar xl">${initials(b.company)}</span><span><p class="eyebrow">APPLICATION ${a.id}</p><h2>${esc(b.company)}</h2><small>${esc(b.name)} · ${esc(b.email)}</small></span></div><div class="review-score"><strong>${a.compliance}%</strong><span>Compliance score</span></div><span class="badge ${statusClass(a.status)}">${applicationStatus}</span></div><div class="content-grid two-one"><section><div class="panel"><div class="panel-head"><div><h2>Company profile</h2><p>Verified business information for this bidder.</p></div></div><div class="profile-facts"><span><small>Company name</small><b>${esc(b.company)}</b></span><span><small>CIN</small><b>${esc(b.cin)}</b></span><span><small>PAN</small><b>${esc(b.pan)}</b></span><span><small>GSTIN</small><b>${esc(b.gstin)}</b></span><span><small>MSME / Udyam</small><b>${esc(b.msme)}</b></span><span><small>Contact</small><b>${esc(b.email)}</b></span><span class="full"><small>Registered address</small><b>${esc(b.address)}</b></span></div></div><div class="panel"><div class="panel-head"><div><h2>Submitted documents</h2><p>Only documents attached to this tender application are shown.</p></div></div><div class="document-list">${rows}</div></div></section><aside><div class="panel compliance-panel"><div class="panel-head"><div><h2>Application decision</h2><p>Status is persisted by the officer API and refreshed from MySQL.</p></div></div><div class="summary-box"><span><b>Application Status:</b> ${applicationStatus}</span><span><b>Blacklist Status:</b> ${blacklisted ? 'Active' : 'Not Blacklisted'}</span>${a.reason ? `<span class="warning-text">${esc(a.reason)}</span>` : ''}</div></div><div class="panel action-panel"><h2>Officer decision</h2><p>Accept or reject this bid. Blacklisting affects the bidder globally.</p><button class="btn btn-primary full" data-action="accept-app" ${acceptDisabled}>${icon('check')} Accept</button><button class="btn btn-outline full" data-action="reject-app" ${rejectDisabled}>Reject</button><button class="btn btn-danger full" data-action="blacklist" ${blacklistDisabled}>${icon('ban')} Blacklist</button></div></aside></div>`; }

// The live handler historically passed a company id to blacklist. Keep the existing call site compatible while routing the action through the authorized application endpoint.
if (window.CPCLApi?.officer) window.CPCLApi.officer.blacklist = (id, reason) => window.CPCLApi.request('/api/officer/applications/' + encodeURIComponent(view.applicationId || id) + '/blacklist', { method: 'POST', body: JSON.stringify({ reason }) });

function bindTenderBackendActions() { if (window.__cpclTenderBackendActionsBound) return; document.addEventListener('click', async event => { const el = event.target?.closest?.('[data-action]'); if (!el) return; const action = el.dataset.action; if (!['publish-new', 'save-edit', 'upload-tender-document', 'confirm-tender-document', 'add-edit-requirement'].includes(action)) return; event.preventDefault(); event.stopImmediatePropagation(); try { if (action === 'add-edit-requirement') { document.querySelector('#edit-requirements')?.insertAdjacentHTML('beforeend', '<div class="requirement-row"><input placeholder="Requirement name"><select><option>Statutory</option><option>Financial</option><option>Experience</option><option>Technical</option></select><select><option>Required</option><option>Optional</option></select><button class="icon-button danger-text" data-action="remove-requirement">' + icon('close') + '</button></div>'); return; } if (action === 'upload-tender-document') { showModal('Upload tender document', '<label><span>Choose PDF or supporting document</span><input id="tender-document-file" type="file" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx"></label>', '<button class="btn btn-outline" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="confirm-tender-document">Upload document</button>'); return; } if (action === 'confirm-tender-document') { const file = document.querySelector('#tender-document-file')?.files?.[0]; if (!file) return toast('Choose a document first', 'error'); await window.CPCLApi.officer.createTenderDocument(view.tenderId, { file }); document.querySelector('#modal-root').innerHTML = ''; await loadBackendData(); render(); toast('Tender document uploaded successfully'); return; } if (action === 'publish-new') { const startDate = document.querySelector('#new-start')?.value; const closingDate = document.querySelector('#new-closing')?.value; const requirements = [...document.querySelectorAll('#requirements-editor .requirement-row')].map(row => { const fields = row.querySelectorAll('input,select'); return { name: fields[0]?.value.trim(), category: String(fields[1]?.value || 'TECHNICAL').toUpperCase(), required: fields[2]?.value !== 'Optional' }; }).filter(requirement => requirement.name); const title = document.querySelector('#new-title')?.value.trim(); const description = document.querySelector('#new-description')?.value.trim(); if (!title || !description || !requirements.length) return toast('Complete tender details and add at least one requirement', 'error'); const response = await window.CPCLApi.officer.createTender({ tenderNumber: document.querySelector('#new-id')?.value.trim() || 'CPCL/2026/' + String(Date.now()).slice(-6), title, description, category: document.querySelector('#new-category')?.value || 'TECHNICAL', startDate, closingDate, requirements }); const file = document.querySelector('#new-file')?.files?.[0]; if (file) await window.CPCLApi.officer.createTenderDocument(response.data.id, { file }); await window.CPCLApi.officer.publish(response.data.id); await loadBackendData(); view.tenderId = response.data.id; view.page = 'officer-tender'; render(); toast('Tender published successfully'); return; } if (action === 'save-edit') { const rows = [...document.querySelectorAll('#edit-requirements .requirement-row')]; const existing = (tender(view.tenderId)?.backendRequirements || []); const keep = new Set(); await window.CPCLApi.officer.updateTender(view.tenderId, { title: document.querySelector('#edit-title')?.value.trim(), description: document.querySelector('#edit-description')?.value.trim(), category: document.querySelector('#edit-category')?.value, closingDate: document.querySelector('#edit-closing')?.value, startDate: document.querySelector('#edit-start')?.value }); for (const row of rows) { const fields = row.querySelectorAll('input,select'); const id = row.dataset.requirementId; const data = { name: fields[0]?.value.trim(), category: String(fields[1]?.value || 'TECHNICAL').toUpperCase(), required: fields[2]?.value !== 'Optional' }; if (!data.name) continue; if (id) { keep.add(id); await window.CPCLApi.officer.updateRequirement(id, data); } else await window.CPCLApi.officer.addRequirement(view.tenderId, data); } for (const requirement of existing) if (!keep.has(requirement.id) && !rows.some(row => row.dataset.requirementId === requirement.id)) await window.CPCLApi.officer.deleteRequirement(requirement.id); await loadBackendData(); view.page = 'officer-tender'; render(); toast('Tender changes saved'); } } catch (error) { toast(apiError(error, 'Unable to update tender.'), 'error'); } }, true); window.__cpclTenderBackendActionsBound = true; }

bindTenderBackendActions();

window.addEventListener('popstate', () => {
  if (!state.session) return;
  const page = pageFromPath(window.location.pathname, state.session.role);
  if (!page) return;
  view.page = page;
  render();
  void (page === 'profile' && state.session.role === 'bidder' ? refreshBidderProfileFromBackend() : Promise.resolve()).then(() => loadBackendData()).then(() => { if (view.page === page) render(); });
});

render();
bindEditableLogin();
if(window.CPCLApi?.store.access && state.session){ loadBackendData().then(render); }
